/* v174: revisão geral não destrutiva dos níveis JLPT.
   Correspondências exatas apenas; não altera níveis preenchidos nem verbetes pessoais. */
(async function kotobaRevisaoGeralJLPTV174(){
 try{
  const response=await fetch("./jlpt-niveis-v111.json",{cache:"no-store"});
  if(!response.ok)throw new Error("Catálogo JLPT indisponível");
  const catalog=await response.json(),lookup=new Map(),conflicts=new Set(),bySpelling=new Map(),spellingConflicts=new Set();
  for(const level of ["N5","N4","N3","N2","N1"]){
   for(const pair of catalog[level]||[]){
    const key=String(pair[0]||"").normalize("NFKC")+"|"+String(pair[1]||"").normalize("NFKC");
    const spelling=String(pair[0]||"").normalize("NFKC");
    if(bySpelling.has(spelling)&&bySpelling.get(spelling)!==level)spellingConflicts.add(spelling);
    else if(!bySpelling.has(spelling))bySpelling.set(spelling,level);
    if(lookup.has(key)&&lookup.get(key)!==level)conflicts.add(key);
    else if(!lookup.has(key))lookup.set(key,level);
   }
  }
  let reviewed=0,updated=0,unmatched=0,skipped=0;
  for(const word of words){
   const id=String(word.id||"");
   if(!/^(?:kotoba|jmdict)/.test(id)){skipped++;continue;}
   if(word.level&&word.level!=="Sem nível"){skipped++;continue;}
   reviewed++;
   const key=String(word.jp||"").normalize("NFKC")+"|"+String(word.kana||"").normalize("NFKC");
   const spelling=String(word.jp||"").normalize("NFKC");
   const exact=conflicts.has(key)?null:lookup.get(key);
   const level=exact||(!spellingConflicts.has(spelling)?bySpelling.get(spelling):null);
   if(!level){unmatched++;continue;}
   word.level=level;
   word.jlptEstimated=false;
   word.jlptSource=exact?"jlpt-niveis-v111:correspondencia-exata":"jlpt-niveis-v111:grafia-univoca";
   updated++;
  }
  if(updated){localStorage.setItem("kotoba_words_v7",JSON.stringify(words));if(typeof render==="function")render();}
  console.info("Kotoba JLPT v174", {reviewed,updated,unmatched,skipped,conflicts:conflicts.size});
 }catch(error){console.warn("Kotoba JLPT v174: revisão não aplicada",error)}
})();


/* v175: exportação local das palavras ainda sem classificação JLPT. */
(function(){
 const button=document.getElementById("exportNoJlpt");
 if(!button)return;
 button.addEventListener("click",function(){
  try{
   const entries=(Array.isArray(words)?words:[]).filter(w=>!String(w.level||"").trim()||String(w.level).trim()==="Sem nível");
   if(!entries.length){alert("Não há palavras sem nível JLPT para exportar.");return;}
   const columns=["Japonês","Leitura kana","Romaji","Tradução PT-BR","Categoria","Nível JLPT","Exemplo japonês","Leitura do exemplo","Tradução do exemplo","ID"];
   const quote=v=>'"'+String(v==null?"":v).replace(/"/g,'""')+'"';
   const data=entries.map(w=>[w.jp,w.kana,w.romaji,w.pt,w.category,w.level||"Sem nível",w.example,w.exampleHiragana,w.translation,w.id]);
   const csv="\uFEFF"+[columns,...data].map(row=>row.map(quote).join(";")).join("\r\n");
   const url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8;"}));
   const anchor=document.createElement("a");
   anchor.href=url;anchor.download="kotoba-palavras-sem-nivel-"+new Date().toISOString().slice(0,10)+".csv";
   document.body.appendChild(anchor);anchor.click();anchor.remove();
   setTimeout(()=>URL.revokeObjectURL(url),30000);
   button.textContent="✓ "+entries.length+" palavras exportadas";
   setTimeout(()=>button.textContent="⬇ Exportar palavras sem nível",4500);
  }catch(error){console.error("Falha ao exportar palavras sem nível:",error);alert("Não foi possível exportar o arquivo CSV.");}
 });
})();


